const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:10px;display:flex;flex-direction:column;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;background:transparent;overflow:hidden}\n.card *{box-sizing:border-box}\n.col,.cols,.form{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\n.cols{flex-direction:row;gap:10px}\n.side{flex:none;width:136px;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\n.cols.big .side{width:168px}\n.main{flex:1}\n.hd{flex:none;display:flex;align-items:center;gap:7px;min-width:0}\n.hm{min-width:0;flex:1}\n.ttl{font-size:14px;font-weight:700;line-height:1.25;color:var(--ink)}\n.stl{font-size:11px;color:var(--muted);line-height:1.3}\n.dot{flex:none;width:9px;height:9px;border-radius:50%}\n.dot.on{background:var(--accent)}\n.dot.off{background:transparent;border:2px solid var(--muted)}\n.acts{flex:none;display:flex;gap:6px}\n.side .acts{flex-direction:column}\n.acts3{flex:none;display:flex;gap:5px}\n.acts3 .btn{flex:1;padding:0 4px}\n.scroll{flex:1;min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px}\n.scroll>*{flex:none}\n.ph{flex:none;font-size:12px;font-weight:700;color:var(--muted)}\n.btn{font:inherit;font-size:12px;min-height:32px;padding:0 10px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;justify-content:center}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:600}\n.btn.sm{min-height:28px;padding:0 8px;font-size:11px}\n.btn.danger{border-color:var(--accent);font-weight:600}\n.btn.back{flex:none;padding:0 9px;font-size:14px}\n.btn:disabled{opacity:.5;cursor:default}\n.btn:focus-visible,.tab:focus-visible,.in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.side .btn{width:100%}\n.tabs{flex:none;display:flex;gap:4px;border-bottom:1px solid var(--line)}\n.tab{font:inherit;font-size:12px;min-height:28px;padding:0 10px;background:transparent;color:var(--muted);border:0;border-bottom:2px solid transparent;cursor:pointer}\n.tab.on{color:var(--ink);font-weight:700;border-bottom-color:var(--accent)}\n.bar{display:flex;gap:6px;flex-wrap:wrap}\n.empty{padding:10px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);text-align:center;display:flex;flex-direction:column;align-items:center;gap:6px}\n.empty p,.sub,.hint,.note,.err{margin:0}\n.sub{color:var(--muted);font-size:11px}\n.note{color:var(--muted);font-size:11px;padding:6px 8px;border-radius:8px;background:var(--soft)}\n.rec{min-width:0;padding:8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);display:flex;flex-direction:column;gap:3px}\n.rec.upd{border-left:3px solid var(--accent)}\n.rh{display:flex;align-items:center;gap:6px;min-width:0}\n.rs{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.rt{flex:none;color:var(--muted);font-size:10px;white-space:nowrap}\n.badge{flex:none;padding:0 6px;border-radius:999px;font-size:10px;line-height:17px;white-space:nowrap;border:1px solid var(--line);color:var(--muted)}\n.badge.upd{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:600}\n.badge.same{background:var(--soft);color:var(--ink)}\n.rl{font-weight:700;font-size:13px;overflow-wrap:anywhere}\n.rd,.rc,.rtp,.rsrc{overflow-wrap:anywhere;color:var(--ink)}\n.rd{color:var(--muted)}\n.rsrc{font-size:11px;color:var(--muted)}\n.rsrc a{color:var(--accent);text-decoration:underline}\n\n.ntc{padding:8px;border-radius:10px;border:1px solid var(--accent);background:var(--soft);color:var(--ink);display:flex;flex-direction:column;align-items:flex-start;gap:5px}\n.ntc .nt{font-weight:700}\n.ntc .nb{overflow-wrap:anywhere}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld.chk{flex-direction:row;align-items:center;gap:6px}\n.fl{font-size:11px;color:var(--muted);font-weight:600}\n.in{width:100%;min-width:0;font:inherit;font-size:12px;min-height:32px;padding:5px 8px;border-radius:8px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink)}\ntextarea.in{resize:none;min-height:60px}\n.cb{width:16px;height:16px;accent-color:var(--accent)}\n.sec{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:2px}\n.tags{display:flex;flex-wrap:wrap;gap:4px}\n.tag{padding:2px 8px;border-radius:999px;background:var(--soft);color:var(--ink);font-size:11px;overflow-wrap:anywhere}\n.site{display:flex;align-items:center;gap:6px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);min-width:0}\n.sm1{flex:1;min-width:0}\n.sn{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.su{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.sl{font-size:10px;color:var(--muted)}\n.sdel{flex:none;display:flex;flex-direction:column;gap:4px}\n.form .fh{flex:none;display:flex;align-items:center;gap:8px}\n.form .ft{font-size:14px;font-weight:700;min-width:0}\n.form .fb{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px}\n.form .fb>*{flex:none}\n.form .ff{flex:none;display:flex;gap:8px;justify-content:flex-end}\n.form .ff .btn{flex:1}\n.hint{font-size:11px;color:var(--muted)}\n.err{font-weight:600;color:var(--ink);padding:6px 8px;border:1px solid var(--accent);border-radius:8px;background:var(--soft)}\n.card[data-size=\"3x3\"]{padding:8px}\n.card[data-size=\"3x3\"] .ttl{font-size:13px}\n.card[data-size=\"3x3\"] .rec{padding:6px}\n.card[data-size=\"3x3\"] .rl{font-size:12px}\n.card[data-size=\"6x3\"] .side .ttl{font-size:13px}\n.card[data-size=\"6x3\"] .btn{min-height:30px}\n.card[data-size=\"6x6\"]{padding:12px}\n@media (prefers-reduced-motion:no-preference){.btn{transition:opacity .15s}}\n";
function freqs(){return [{value:'hourly',label:'每小时'},{value:'6h',label:'每 6 小时'},{value:'daily',label:'每天'},{value:'weekly',label:'每周'},{value:'monthly',label:'每月'}];}
function freqLabel(v){const f=freqs().find(x=>x.value===v);return f?f.label:'每天';}
function pad2(n){return n<10?'0'+n:String(n);}
function fmtTime(ms){if(!ms)return '';const d=new Date(ms);return (d.getMonth()+1)+'月'+d.getDate()+'日 '+pad2(d.getHours())+':'+pad2(d.getMinutes());}
function shortUrl(u){return String(u||'').replace(/^https?:\/\/(www\.)?/i,'').replace(/\/$/,'');}
function hostOf(u){const m=String(u||'').match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);return m?m[1]:String(u||'');}
function validUrl(u){return /^https?:\/\/[^\s\/?#.]+\.[^\s\/?#]+/i.test(String(u||'').trim());}
function normS(s){
  const b=s||{};
  return {
    sites:Array.isArray(b.sites)?b.sites:[],
    topicsText:typeof b.topicsText==='string'?b.topicsText:'',
    freq:b.freq||'daily',
    paused:!!b.paused,
    records:Array.isArray(b.records)?b.records:[]
  };
}
function patchS(st,p){return Object.assign({},st||{},normS(st),p);}
function topicsOf(t){return String(t||'').split(/[\n,，、;；]+/).map(x=>x.trim()).filter(Boolean);}
function sortRecs(list){return list.slice().sort((a,b)=>(b.at||0)-(a.at||0));}
function prevOf(sorted,rec){
  const i=sorted.indexOf(rec);
  for(let k=i+1;k<sorted.length;k++){if(sorted[k].siteId===rec.siteId)return sorted[k];}
  return null;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,size}=ctx;
  const s=normS(state);
  const sites=s.sites;
  const recs=sortRecs(s.records);
  const topics=topicsOf(s.topicsText);
  const lastAt=recs.length?recs[0].at:0;
  function h(tag,attrs,...kids){return el(tag,attrs||{},...kids.filter(k=>k!==null&&k!==undefined&&k!==false));}
  function setUi(p){Object.assign(ui,p);redraw();}
  function errMsg(e){return (e&&e.message)?e.message:'请稍后重试';}
  function failNote(e){setUi({notice:{kind:'err',text:'保存失败，已保留原数据：'+errMsg(e)}});}
  function btn(label,onClick,o){
    const opt=o||{};
    return h('button',{type:'button',class:'btn'+(opt.primary?' pri':'')+(opt.cls?' '+opt.cls:''),disabled:!!opt.disabled,onclick:onClick},label);
  }

  function checkNow(){
    if(!sites.length){setUi({notice:{kind:'warn',text:'先添加至少一个官网链接，再检查。'}});return;}
    setUi({notice:{kind:'warn',title:'检查未接入',text:'当前平台没有读取官网页面或 AI 比对的接口，无法自动查看官网。链接、关注点、频率和已有记录都已保留。你可以自己打开官网，再点「登记结果」，卡片会和上一次对比并保留出处。'}});
  }
  function togglePause(){
    update(st=>patchS(st,{paused:!normS(st).paused})).catch(failNote);
  }
  function setFreq(v){
    update(st=>patchS(st,{freq:v})).catch(failNote);
  }
  function openSite(){setUi({form:{type:'site',draft:{url:'',name:''},error:''},notice:null});}
  function openTopics(){setUi({form:{type:'topics',draft:{topicsText:s.topicsText},error:''},notice:null});}
  function openRecord(){
    if(!sites.length){setUi({notice:{kind:'warn',text:'先添加官网链接，才能登记检查结果。'}});return;}
    setUi({form:{type:'record',draft:{siteId:sites[0].id,headline:'',hasUpdate:true,change:'',topic:'',source:sites[0].url},error:''},notice:null});
  }
  function closeForm(){setUi({form:null});}
  function formErr(t){ui.form.error=t;redraw();}
  function saveSite(){
    const d=ui.form.draft;
    const url=String(d.url||'').trim();
    if(!validUrl(url)){formErr('请填写以 http:// 或 https:// 开头的官网链接');return;}
    if(sites.some(x=>x.url===url)){formErr('这个链接已经添加过了');return;}
    const site={id:uid(),url:url,name:String(d.name||'').trim()||hostOf(url)};
    commit(st=>{
      const b=normS(st);
      if(b.sites.some(x=>x.url===url))return patchS(st,{});
      return patchS(st,{sites:b.sites.concat([site])});
    },Object.assign({},ui,{form:null,tab:'monitor',notice:null})).catch(e=>formErr('保存失败：'+errMsg(e)));
  }
  function saveTopics(){
    const text=String(ui.form.draft.topicsText||'');
    commit(st=>patchS(st,{topicsText:text}),Object.assign({},ui,{form:null})).catch(e=>formErr('保存失败：'+errMsg(e)));
  }
  function saveRecord(){
    const d=ui.form.draft;
    const site=sites.find(x=>x.id===d.siteId);
    const headline=String(d.headline||'').trim();
    const source=String(d.source||'').trim()||(site?site.url:'');
    if(!site){formErr('请选择站点');return;}
    if(!headline){formErr('请填写这次看到的版本号或最新标题');return;}
    if(!validUrl(source)){formErr('出处需要是 http:// 或 https:// 开头的链接');return;}
    const rec={id:uid(),siteId:site.id,siteName:site.name,siteUrl:site.url,at:Date.now(),headline:headline,hasUpdate:!!d.hasUpdate,change:String(d.change||'').trim(),source:source,topic:String(d.topic||'')};
    commit(st=>{const b=normS(st);return patchS(st,{records:b.records.concat([rec])});},Object.assign({},ui,{form:null,tab:'updates',notice:null})).catch(e=>formErr('保存失败：'+errMsg(e)));
  }
  function removeSite(id){
    ui.delId=null;
    update(st=>patchS(st,{sites:normS(st).sites.filter(x=>x.id!==id)})).catch(failNote);
  }


  function field(f,d){
    const cur=d[f.key];
    let input;
    if(f.type==='textarea'){
      input=h('textarea',{class:'in',rows:3,'aria-label':f.label,placeholder:f.placeholder||'',value:cur||'',oninput:e=>{d[f.key]=e.target.value;}});
    }else if(f.type==='select'){
      input=h('select',{class:'in','aria-label':f.label,onchange:e=>{d[f.key]=e.target.value;if(f.onPick)f.onPick(e.target.value);}},
        ...f.options.map(o=>h('option',o.value===cur?{value:o.value,selected:true}:{value:o.value},o.label)));
      input.value=cur||'';
    }else if(f.type==='checkbox'){
      input=h('input',{type:'checkbox',class:'cb',checked:!!cur,onchange:e=>{d[f.key]=e.target.checked;}});
      return h('label',{class:'fld chk'},input,h('span',{},f.label));
    }else{
      input=h('input',{type:'text',class:'in','aria-label':f.label,placeholder:f.placeholder||'',value:cur||'',oninput:e=>{d[f.key]=e.target.value;}});
    }
    return h('label',{class:'fld'},h('span',{class:'fl'},f.label),input);
  }
  function formView(){
    const f=ui.form;
    const d=f.draft;
    let title='',fields=[],onSave=null,hint='';
    if(f.type==='site'){
      title='添加官网链接';onSave=saveSite;
      fields=[{key:'url',label:'官网链接',placeholder:'https://example.com/changelog'},{key:'name',label:'名称（可不填）',placeholder:'默认用域名'}];
    }else if(f.type==='topics'){
      title='关心的内容';onSave=saveTopics;
      fields=[{key:'topicsText',label:'每行一项，或用逗号分隔',type:'textarea',placeholder:'例如：价格调整、新功能、API 变更'}];
    }else{
      title='登记检查结果';onSave=saveRecord;
      hint='自己打开官网看过后在这里记录；卡片会与该站点上一次记录对比。';
      fields=[
        {key:'siteId',label:'站点',type:'select',options:sites.map(x=>({value:x.id,label:x.name})),onPick:function(v){
          const prev=sites.find(x=>x.url===d.source);
          const nx=sites.find(x=>x.id===v);
          if(!d.source||prev)d.source=nx?nx.url:'';
          redraw();
        }},
        {key:'headline',label:'这次看到的最新版本 / 标题',placeholder:'例如 v2.4 发布说明'},
        {key:'hasUpdate',label:'比上次有更新',type:'checkbox'},
        {key:'change',label:'变化说明（和上次比变了什么）',type:'textarea',placeholder:'新增、调整或移除了什么'}
      ];
      if(topics.length)fields.push({key:'topic',label:'对应的关注点',type:'select',options:[{value:'',label:'（不指定）'}].concat(topics.map(t=>({value:t,label:t})))});
      fields.push({key:'source',label:'出处链接',placeholder:'默认用站点链接'});
    }
    return h('div',{class:'form'},
      h('div',{class:'fh'},btn('‹ 返回',closeForm,{cls:'sm'}),h('div',{class:'ft'},title)),
      h('div',{class:'fb'},
        hint?h('p',{class:'hint'},hint):null,
        ...fields.map(x=>field(x,d)),
        f.error?h('p',{class:'err',role:'alert'},'⚠ '+f.error):null),
      h('div',{class:'ff'},btn('取消',closeForm),btn('保存',onSave,{primary:true})));
  }

  function badgeOf(kind){return kind==='base'?'基线':(kind==='upd'?'有更新':'无变化');}
  function recItem(rec){
    const prev=prevOf(recs,rec);
    const kind=!prev?'base':(rec.hasUpdate?'upd':'same');
    const diff=!prev?'首次记录，作为之后对比的基线'
      :(rec.hasUpdate?'相比上次（'+fmtTime(prev.at)+'）：'+(prev.headline||'无标题')+' → '+rec.headline
        :'与上次（'+fmtTime(prev.at)+'）相比没有更新');
    return h('article',{class:'rec '+kind},
      h('div',{class:'rh'},h('span',{class:'badge '+kind},badgeOf(kind)),h('span',{class:'rs'},rec.siteName||hostOf(rec.siteUrl)),h('span',{class:'rt'},fmtTime(rec.at))),
      h('div',{class:'rl'},rec.headline),
      h('div',{class:'rd'},diff),
      rec.change?h('div',{class:'rc'},'变化：'+rec.change):null,
      rec.topic?h('div',{class:'rtp'},'关注点：'+rec.topic):null,
      rec.source?h('div',{class:'rsrc'},'出处：',h('a',{href:rec.source,target:'_blank',rel:'noopener noreferrer'},shortUrl(rec.source))):null);
  }

  function updatesPanel(){
    const list=ui.onlyUpd?recs.filter(r=>r.hasUpdate):recs;
    const out=[h('div',{class:'bar'},
      btn('＋ 登记结果',openRecord,{primary:true,cls:'sm'}),
      btn(ui.onlyUpd?'✓ 只看有更新':'只看有更新',()=>setUi({onlyUpd:!ui.onlyUpd}),{cls:'sm'}))];
    if(!sites.length){
      out.push(h('div',{class:'empty'},h('p',{},'还没有要跟踪的官网。'),btn('添加官网链接',openSite,{cls:'sm'})));
    }else if(!recs.length){
      out.push(h('div',{class:'empty'},h('p',{},'还没有检查记录。'),h('p',{class:'sub'},'自动检查未接入，查看官网后可手动登记。')));
    }else if(!list.length){
      out.push(h('div',{class:'empty'},h('p',{},'没有标记为「有更新」的记录。')));
    }else{
      list.forEach(r=>out.push(recItem(r)));
    }
    return out;
  }

  function monitorPanel(){
    const out=[];
    out.push(h('label',{class:'fld'},h('span',{class:'fl'},'检查频率'),
      (function(){
        const sel=h('select',{class:'in','aria-label':'检查频率',onchange:e=>setFreq(e.target.value)},
          ...freqs().map(o=>h('option',o.value===s.freq?{value:o.value,selected:true}:{value:o.value},o.label)));
        sel.value=s.freq;
        return sel;
      })()));
    out.push(h('div',{class:'sec'},h('span',{class:'fl'},'关心的内容'),btn(topics.length?'编辑':'填写',openTopics,{cls:'sm'})));
    out.push(topics.length?h('div',{class:'tags'},...topics.map(t=>h('span',{class:'tag'},t))):h('p',{class:'sub'},'还没有填写关注点。'));
    out.push(h('div',{class:'sec'},h('span',{class:'fl'},'官网链接（'+sites.length+'）'),btn('＋ 添加',openSite,{cls:'sm',primary:true})));
    if(!sites.length)out.push(h('p',{class:'sub'},'还没有添加官网链接。'));
    sites.forEach(x=>{
      const last=recs.find(r=>r.siteId===x.id);
      out.push(h('div',{class:'site'},
        h('div',{class:'sm1'},h('div',{class:'sn'},x.name),h('div',{class:'su'},shortUrl(x.url)),h('div',{class:'sl'},last?'最近记录：'+fmtTime(last.at):'暂无记录')),
        ui.delId===x.id
          ?h('div',{class:'sdel'},btn('确认删除',()=>removeSite(x.id),{cls:'sm danger'}),btn('取消',()=>setUi({delId:null}),{cls:'sm'}))
          :btn('删除',()=>setUi({delId:x.id}),{cls:'sm'})));
    });
    if(sites.length)out.push(h('p',{class:'sub'},'删除站点不会删除它的历史检查记录。'));
    out.push(h('p',{class:'note'},'后台定时检查未接入：频率和暂停状态已保存，但目前不会自动执行，需要时点「立即查一次」或手动登记。'));
    return out;
  }


  function noticeEl(){
    const n=ui.notice;
    if(!n)return null;
    return h('div',{class:'ntc '+n.kind,role:'status'},
      h('div',{class:'nt'},(n.kind==='err'?'⚠ ':'ⓘ ')+(n.title||(n.kind==='err'?'出错了':'提示'))),
      h('div',{class:'nb'},n.text),
      btn('知道了',()=>setUi({notice:null}),{cls:'sm'}));
  }
  function statusLine(){
    return sites.length+' 个站点 · '+(s.paused?'已暂停':freqLabel(s.freq))+((lastAt&&size!=='6x3')?' · 最近记录 '+fmtTime(lastAt):'');
  }
  function head(back){
    return h('div',{class:'hd'},
      back?btn('‹',()=>setUi({expanded:false}),{cls:'sm back'}):null,
      h('span',{class:'dot '+(s.paused?'off':'on'),'aria-hidden':'true'}),
      h('div',{class:'hm'},h('div',{class:'ttl'},'产品更新跟踪'),h('div',{class:'stl'},statusLine())));
  }
  function actions(){
    return h('div',{class:'acts'},
      btn('立即查一次',checkNow,{primary:true}),
